-- TS-034: dedicated VVH Trip Shed staff identity source.
-- Source: data/trip-shed/vvh-2025-08/source/VVH STAFF COMPLETE DETAILS.xlsx
-- Source row without HRMS ID (Bapu Waghmare) is intentionally excluded.
-- Source correction: source row 42 Sultan Khan is assigned HRMS ID WRBXYS;
-- KHTLDH remains assigned to Shankar Meena using PF 00229817651.
CREATE TABLE IF NOT EXISTS div_trip_shed_staff (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  shed_id INT NOT NULL,
  serial_no SMALLINT UNSIGNED NULL,
  source_row_no SMALLINT UNSIGNED NULL,
  staff_name VARCHAR(160) NOT NULL,
  pf_number VARCHAR(20) NULL,
  designation VARCHAR(60) NULL,
  dob_source VARCHAR(20) NULL,
  doa_source VARCHAR(20) NULL,
  dor_source VARCHAR(20) NULL,
  vvh_posting_year SMALLINT NULL,
  pan_number VARCHAR(20) NULL,
  umid_card_no VARCHAR(30) NULL,
  aadhaar_source VARCHAR(30) NULL,
  hrms_id VARCHAR(20) NOT NULL,
  email VARCHAR(160) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  source_file VARCHAR(255) NOT NULL,
  source_sheet VARCHAR(120) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_trip_shed_staff_hrms (shed_id, hrms_id),
  KEY ix_trip_shed_staff_lookup (shed_id, staff_name, pf_number),
  CONSTRAINT fk_trip_shed_staff_shed FOREIGN KEY (shed_id) REFERENCES div_trip_sheds(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE staff_name=VALUES(staff_name),pf_number=VALUES(pf_number),designation=VALUES(designation),dob_source=VALUES(dob_source),doa_source=VALUES(doa_source),dor_source=VALUES(dor_source),vvh_posting_year=VALUES(vvh_posting_year),pan_number=VALUES(pan_number),umid_card_no=VALUES(umid_card_no),aadhaar_source=VALUES(aadhaar_source),email=VALUES(email),is_active=VALUES(is_active),source_file=VALUES(source_file),source_sheet=VALUES(source_sheet);
